DELETE FROM PROJECT_TASK   /* QueryID : com.demo.proworks.task.design.deleteDesign */ 
WHERE   
        TASK_ID     = #{taskId}

mapper.select:
SELECT /* QueryID : com.demo.proworks.task.design.selectListDesign */ taskId, taskName, taskDes, taskStatus, isTest, isDesign, ptTaskId, deTaskId, taskDepth, taskSt, taskEt, taskRst, taskRet, taskAsi, taskRate, pjtId, userId, ptTaskName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT t.task_id as taskId, t.task_name as taskName, t.task_des as taskDes, t.task_status as taskStatus, t.is_test as isTest, t.is_design as isDesign, t.pt_task_id as ptTaskId, t.de_task_id as deTaskId, t.task_depth as taskDepth, t.task_st as taskSt, t.task_et as taskEt, t.task_rst as taskRst, t.task_ret as taskRet, t.task_asi as taskAsi, t.task_rate as taskRate, t.pjt_id as pjtId, t.user_id as userId, pt.task_name as ptTaskName -- 상위 업무명 (조인으로 가져오기) FROM project_task t LEFT JOIN project_task pt ON t.pt_task_id = pt.task_id -- 상위 업무와 조인 WHERE t.pjt_id = #{pjtId} AND t.user_id = #{userId}
AND t.task_name like CONCAT('%', #{scTaskName}, '%')
AND t.task_status like CONCAT('%', #{scTaskStatus}, '%')
AND t.is_test = #{scIsTest}
ORDER BY t.task_depth, t.task_id -- 정렬 조건 추가 ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT /* QueryID : com.demo.proworks.task.design.selectListDesign */ taskId, taskName, taskDes, taskStatus, isTest, isDesign, ptTaskId, deTaskId, taskDepth, taskSt, taskEt, taskRst, taskRet, taskAsi, taskRate, pjtId, userId, ptTaskName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT t.task_id as taskId, t.task_name as taskName, t.task_des as taskDes, t.task_status as taskStatus, t.is_test as isTest, t.is_design as isDesign, t.pt_task_id as ptTaskId, t.de_task_id as deTaskId, t.task_depth as taskDepth, t.task_st as taskSt, t.task_et as taskEt, t.task_rst as taskRst, t.task_ret as taskRet, t.task_asi as taskAsi, t.task_rate as taskRate, t.pjt_id as pjtId, t.user_id as userId, pt.task_name as ptTaskName -- 상위 업무명 (조인으로 가져오기) FROM project_task t LEFT JOIN project_task pt ON t.pt_task_id = pt.task_id -- 상위 업무와 조인 WHERE t.pjt_id = #{pjtId} AND t.user_id = #{userId} AND t.is_design = 1
AND t.task_id like CONCAT('%', #{scTaskId}, '%')
AND t.task_name like CONCAT('%', #{scTaskName}, '%')
AND t.task_status like CONCAT('%', #{scTaskStatus}, '%')
AND t.is_test = #{scIsTest}
ORDER BY t.task_depth, t.task_id -- 정렬 조건 추가 ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}


SELECT /* QueryID : com.demo.proworks.task.design.selectListCountDesign */
    COUNT(*) totcnt
FROM project_task
WHERE is_design = 1                    
  AND pjt_id = #{pjtId} 
  AND user_id = #{userId}

     AND task_id like CONCAT('%', #{scTaskId}, '%')


    AND task_name like CONCAT('%', #{scTaskName}, '%')


    AND task_status like CONCAT('%', #{scTaskStatus}, '%')


    AND is_test = #{scIsTest}

SELECT /* QueryID : com.demo.proworks.task.design.selectListCountDevelop */ COUNT(*) totcnt FROM project_task WHERE is_design = 0 -- 개발 업무만 (기존 stg_id = 6 대체) AND pjt_id = #{pjtId} AND user_id = #{userId}
AND task_id like CONCAT('%', #{scTaskId}, '%')
AND pt_task_id like CONCAT('%', #{scPtTaskId}, '%')
AND task_name like CONCAT('%', #{scTaskName}, '%')
AND task_status like CONCAT('%', #{scTaskStatus}, '%')
AND is_test = #{scIsTest}

WITH RECURSIVE task_tree AS ( -- 1단계: 최상위 업무들 SELECT task_id, task_name, pt_task_id as pt_task_id, task_depth, is_design, pjt_id, CAST( CONCAT( CASE WHEN is_design = 1 THEN '1' ELSE '2' END, LPAD(CAST(SUBSTRING(task_id, 5) AS UNSIGNED), 10, '0') ) AS VARCHAR(200) ) as tree_path FROM project_task WHERE pt_task_id IS NULL AND pjt_id = #{pjtId} AND is_design=1
UNION ALL
-- 2-3단계: 하위 업무들 재귀 조회 SELECT t.task_id, t.task_name, t.pt_task_id as pt_task_id, t.task_depth, t.is_design, t.pjt_id, CAST( CONCAT( tt.tree_path, '-', CASE WHEN t.is_design = 1 THEN '1' ELSE '2' END, LPAD(CAST(SUBSTRING(t.task_id, 5) AS UNSIGNED), 10, '0') ) AS VARCHAR(200) ) as tree_path FROM project_task t INNER JOIN task_tree tt ON t.pt_task_id = tt.task_id WHERE t.pjt_id = #{pjtId} AND t.is_design=1 ) SELECT task_id as taskId, task_name as taskName, pt_task_id as ptTaskId, task_depth as taskDepth, CASE WHEN is_design = 1 THEN '설계' ELSE '개발' END as taskType, tree_path, -- 디버깅용 pjt_id as pjtId FROM task_tree ORDER BY tree_path;

WITH RECURSIVE task_tree AS ( -- 1단계: 최상위 업무들 SELECT task_id, task_name, task_status, task_st, task_et, task_rst, task_ret, task_asi, task_rate, pt_task_id as pt_task_id, task_depth, is_design, pjt_id, CAST( CONCAT( CASE WHEN is_design = 1 THEN '1' ELSE '2' END, LPAD(CAST(SUBSTRING(task_id, 5) AS UNSIGNED), 10, '0') ) AS VARCHAR(200) ) as tree_path FROM project_task WHERE pt_task_id IS NULL AND pjt_id = #{pjtId}
UNION ALL
-- 2-3단계: 하위 업무들 재귀 조회 SELECT t.task_id, t.task_name, t.task_status, t.task_st, t.task_et, t.task_rst, t.task_ret, t.task_asi, t.task_rate, t.pt_task_id as pt_task_id, t.task_depth, t.is_design, t.pjt_id, CAST( CONCAT( tt.tree_path, '-', CASE WHEN t.is_design = 1 THEN '1' ELSE '2' END, LPAD(CAST(SUBSTRING(t.task_id, 5) AS UNSIGNED), 10, '0') ) AS VARCHAR(200) ) as tree_path FROM project_task t INNER JOIN task_tree tt ON t.pt_task_id = tt.task_id WHERE t.pjt_id = #{pjtId} ) SELECT task_id as taskId, task_name as taskName, task_status as taskStatus, task_st as taskSt, task_et as taskEt, task_rst as taskRst, task_ret as taskRet, task_asi as taskAsi, task_rate as taskRate, pt_task_id as ptTaskId, task_depth as taskDepth, CASE WHEN is_design = 1 THEN '설계' ELSE '개발' END as taskType, tree_path, -- 디버깅용 pjt_id as pjtId FROM task_tree ORDER BY tree_path;

WITH RECURSIVE child_depth_update AS ( SELECT task_id, task_depth as new_depth, 0 as level_depth FROM project_task WHERE task_id = #{taskId}
UNION ALL
SELECT t.task_id, cdu.new_depth + 1 as new_depth, cdu.level_depth + 1 as level_depth FROM project_task t JOIN child_depth_update cdu ON t.pt_task_id = cdu.task_id WHERE cdu.level_depth < 10 ) SELECT task_id as taskId, new_depth as taskDepth FROM child_depth_update WHERE task_id != #{taskId}
